+const reloadStateFilename = "reload-status.json"
+
+// transactionalReload serializes configuration application and retains the last
+// configuration which was completely applied. Its status is intentionally kept
+// independently from the config success metrics: it describes whole attempts.
+type transactionalReload struct {
+	mu       sync.RWMutex
+	state    api_v1.ReloadStatus
+	lastGood *config.Config
+	path     string
+}
+
+func newTransactionalReload(storageDir string) *transactionalReload {
+	t := &transactionalReload{path: filepath.Join(storageDir, reloadStateFilename)}
+	// A missing or malformed diagnostic file is not a startup error.
+	b, err := os.ReadFile(t.path)
+	if err == nil && json.Unmarshal(b, &t.state) == nil {
+		return t
+	}
+	t.state = api_v1.ReloadStatus{ErrorCategory: "none", AppliedReloaders: []string{}, ReloaderTimingsMS: map[string]float64{}}
+	return t
+}
+
+func (t *transactionalReload) Status() api_v1.ReloadStatus {
+	t.mu.RLock()
+	defer t.mu.RUnlock()
+	return t.state.Clone()
+}
+
+func (t *transactionalReload) setInitialConfig(conf *config.Config) {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	t.lastGood = conf
+}
+
+func (t *transactionalReload) record(s api_v1.ReloadStatus) {
+	t.mu.Lock()
+	t.state = s
+	b, err := json.Marshal(s)
+	if err == nil {
+		tmp := t.path + ".tmp"
+		if err = os.WriteFile(tmp, b, 0o644); err == nil {
+			_ = os.Rename(tmp, t.path)
+		}
+	}
+	t.mu.Unlock()
+}
+
+func (t *transactionalReload) loadError(err error) error {
+	t.record(t.newStatus("load_error", err))
+	return err
+}
+
+func (t *transactionalReload) apply(conf *config.Config, rls []reloader) error {
+	status := t.newStatus("none", nil)
+	for _, rl := range rls {
+		start := time.Now()
+		err := rl.reloader(conf)
+		status.ReloaderTimingsMS[rl.name] = float64(time.Since(start)) / float64(time.Millisecond)
+		if err != nil {
+			status.LastReloadSuccessful = false
+			status.ErrorCategory = "apply_error"
+			status.ErrorMessage = err.Error()
+			status.FailedReloader = rl.name
+			if len(status.AppliedReloaders) > 0 {
+				status.RollbackAttempted = true
+				t.mu.RLock()
+				previous := t.lastGood
+				t.mu.RUnlock()
+				if previous == nil {
+					status.RollbackSuccessful = false
+					status.ErrorCategory = "rollback_error"
+					status.ErrorMessage = "no last known-good configuration available for rollback"
+				} else if rollbackErr := applyReloaders(previous, rls); rollbackErr != nil {
+					status.RollbackSuccessful = false
+					status.ErrorCategory = "rollback_error"
+					status.ErrorMessage = rollbackErr.Error()
+				} else {
+					status.RollbackSuccessful = true
+				}
+			}
+			t.record(status)
+			return fmt.Errorf("failed to apply configuration with reloader %q: %w", rl.name, err)
+		}
+		status.AppliedReloaders = append(status.AppliedReloaders, rl.name)
+	}
+	status.LastReloadSuccessful = true
+	t.mu.Lock()
+	t.lastGood = conf
+	t.mu.Unlock()
+	t.record(status)
+	return nil
+}
+
+func (t *transactionalReload) newStatus(category string, err error) api_v1.ReloadStatus {
+	s := api_v1.ReloadStatus{
+		LastReloadID:      time.Now().UTC().Format(time.RFC3339),
+		ErrorCategory:      category,
+		AppliedReloaders:   []string{},
+		ReloaderTimingsMS:  map[string]float64{},
+	}
+	if err != nil {
+		s.ErrorMessage = err.Error()
+	}
+	return s
+}
+
+func applyReloaders(conf *config.Config, rls []reloader) error {
+	for _, rl := range rls {
+		if err := rl.reloader(conf); err != nil {
+			return fmt.Errorf("rollback failed in reloader %q: %w", rl.name, err)
+		}
+	}
+	return nil
+}
